/**
 * Bit-identical port of Go's math/rand rngSource (607-tap lagged Fibonacci).
 *
 * server/game seeds its match with rand.New(rand.NewSource(seed)); the JS
 * engine must produce the same wind/AI/crit sequence for the same seed, so
 * this module copies rngSource.Seed/Int63 and rand.Rand's Int31n/Intn/Float64
 * verbatim from $GOROOT/src/math/rand (BSD licence). RNG_COOKED is generated by
 * scripts/gen_engine_assets.go straight out of that file.
 */
import { RNG_COOKED } from './rng-cooked.js?v=24';

const RNG_LEN = 607;
const RNG_TAP = 273;
const RNG_MASK = (1n << 63n) - 1n;
const INT32_MAX = 2147483647; // 1<<31 - 1

function seedrand(x) {
  const A = 48271;
  const Q = 44488;
  const R = 3399;
  const hi = Math.trunc(x / Q);
  const lo = x % Q;
  let v = A * lo - R * hi;
  if (v < 0) v += INT32_MAX;
  return v;
}

export class GoRand {
  constructor(seed = 1) {
    this.vec = new BigInt64Array(RNG_LEN);
    this.tap = 0;
    this.feed = 0;
    this.seed(seed);
  }

  seed(seed) {
    this.tap = 0;
    this.feed = RNG_LEN - RNG_TAP;
    let s = BigInt(Math.trunc(seed)) % BigInt(INT32_MAX);
    if (s < 0n) s += BigInt(INT32_MAX);
    if (s === 0n) s = 89482311n;
    let x = Number(s);
    for (let i = -20; i < RNG_LEN; i += 1) {
      x = seedrand(x);
      if (i >= 0) {
        let u = BigInt(x) << 40n;
        x = seedrand(x);
        u ^= BigInt(x) << 20n;
        x = seedrand(x);
        u ^= BigInt(x);
        u ^= RNG_COOKED[i];
        this.vec[i] = u;
      }
    }
    return this;
  }

  /** int64(0 .. 2^63-1) — Go rngSource.Int63. */
  int63() {
    this.tap -= 1;
    if (this.tap < 0) this.tap += RNG_LEN;
    this.feed -= 1;
    if (this.feed < 0) this.feed += RNG_LEN;
    const x = this.vec[this.feed] + this.vec[this.tap];
    this.vec[this.feed] = x;
    return x & RNG_MASK;
  }

  /** int32(0 .. 2^31-1) — Go Rand.Int31. */
  int31() {
    return Number(this.int63() >> 32n);
  }

  /** Uniform in [0, n) — Go Rand.Int31n's rejection path. */
  int31n(n) {
    const m = n | 0;
    if (m <= 0) throw new Error(`invalid argument to Int31n: ${n}`);
    if ((m & (m - 1)) === 0) return this.int31() & (m - 1);
    const max = 2147483647 - (2147483648 % m);
    let v = this.int31();
    while (v > max) v = this.int31();
    return v % m;
  }

  /** Go Rand.Intn. */
  intn(n) {
    if (n <= 0) throw new Error(`invalid argument to Intn: ${n}`);
    return this.int31n(n);
  }

  /** Go Rand.Float64. */
  float64() {
    for (;;) {
      const f = Number(this.int63()) / 9223372036854775808;
      if (f !== 1) return f;
    }
  }

  /** Go game.randomInt: min + Intn(max-min), empty range → min. */
  randomInt(minInclusive, maxExclusive) {
    if (maxExclusive <= minInclusive) return minInclusive;
    return minInclusive + this.intn(maxExclusive - minInclusive);
  }
}
